      "note": "heading1 '결과는 no Pinning이 젤 빠르다..'는 P0073F0001에 그대로 보존됨."
    },
    "p73:e574": {
      "state": "no_research",
      "fact_ids": [],
      "note": "'흠 ..'은 단순 감탄/반응성 머리글로 연구 내용이 없어 승인된 사실에 대응하지 않음."
    },
    "p73:e575": {
      "state": "represented",
      "fact_ids": ["P0073F0002"],
      "note": "머리글 '① cudaHostAlloc이 8.64초 더 걸린 이유'는 하위 문단(p73:e576)과 함께 P0073F0002에서 대표됨."
    },
    "p73:e576": {
      "state": "represented",
      "fact_ids": ["P0073F0002"],
      "note": "CPU 루프 내 복사 오버헤드 누적(8.64초, 회당 약 9.4μs) 해석이 P0073F0002의 관측·측정값으로 보존됨."
    },
    "p73:e577": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "머리글 '② No Pinning과 Pinned 메모리 차이가 크지 않은 이유'는 하위 항목과 함께 P0073F0003에서 대표됨."
    },
    "p73:e578": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "하위 항목 머리글 '1. 극도로 작은 입력 크기 (1 KB):'는 P0073F0003의 맥락으로 보존됨."
    },
    "p73:e579": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "입력 벡터 1,024 Byte(1 KB), L1/L2 캐시, 스테이징 버퍼 복사 지연 0.1μs 미만 서술이 P0073F0003에 보존됨."
    },
    "p73:e580": {
      "state": "represented",
      "fact_ids": ["P0073F0003"],
      "note": "GPU 연산 시간 지배적(85% 이상, 약 716μs), 전송 시간 비중 1~2μs 수준 서술이 P0073F0003에 보존됨."
    },
    "p73:e581": {
      "state": "represented",
      "fact_ids": ["P0073F0004"],
      "note": "'No pinning이 pinned memory보다 더 빠른 이유를 더 자세히 보려 한다'는 추가 분석 의도가 P0073F0004에 보존됨."
    },
    "p73:img0:e0": {
      "state": "represented",
      "fact_ids": ["P0073F0005"],
      "note": "표 제목 '1. 3가지 메모리 방식 벤치마크 결과 비교'가 P0073F0005의 source_ids에 포함됨."
    },
    "p73:img0:e1": {
      "state": "represented",
      "fact_ids": ["P0073F0005"],
      "note": "실험 조건(backward_only method=2, CUDA Graph Separate graph_mode=1, 총 920,000회 연산)이 P0073F0005의 conditions로 보존됨."
    },
    "p73:img0:e2": {
      "state": "represented",
      "fact_ids": ["P0073F0005"],
      "note": "구조화된 벤치마크 표(전체 실행 시간, infer_s, bound_s, 평균/중위/꼬리 지연, 지터, 순수 GPU 커널 시간, 처리량)가 P0073F0005의 측정값들로 보존됨. structured_table_manifest complete=true이나 핵심 요약이 이미 facts에 연결됨."
    }
  }
}
